 begin perform public.cbgpu_school_extensions_api('messages','{"scope":"SCHOOL","school_id":"fixture-effective-b"}');raise exception 'DISABLED_COMMUNITY_AVAILABLE' using errcode='XX000';exception when insufficient_privilege then null;end;
 begin perform public.cbgpu_school_extensions_api('message_create','{"scope":"PUBLIC","body":"Disabled global posting"}');raise exception 'DISABLED_PUBLIC_COMMUNITY_WRITE' using errcode='XX000';exception when insufficient_privilege then null;end;
